def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    if horizon <= 0:
        return []
    x = []
    for v in history:
        try:
            z = float(v)
            x.append(z if math.isfinite(z) else 0.0)
        except (TypeError, ValueError):
            x.append(0.0)
    if not x:
        return [0.0] * horizon
    p = 24 if 'hour' in frequency.lower() else max(2, min(24, len(x) // 4))
    n = len(x)
    current_start = n - (n % p)
    ratios = []
    for i in range(max(current_start, p), n):
        a, b = x[i], x[i - p]
        if a > 1e-12 and b > 1e-12:
            ratios.append(a / b)
    level = statistics.median(ratios) if len(ratios) >= 4 else 1.0
    level = max(0.75, min(1.50, level))
    global_pos = [v for v in x[-4 * p:] if v > 1e-12]
    fallback = statistics.median(global_pos) if global_pos else 0.0
    out = []
    for k in range(horizon):
        target = n + k
        phase = target % p
        phase_items = [(i, x[i]) for i in range(phase, n, p)][-4:]
        vals = [v for _, v in phase_items]
        zero_vote = sum(v <= 1e-12 for v in vals)
        if len(vals) >= 3 and zero_vote >= 3:
            out.append(0.0)
            continue
        observed_current = [(i, v) for i, v in phase_items if i >= current_start]
        if observed_current and target // p > current_start // p:
            value = observed_current[-1][1]
        else:
            pos = [v for _, v in phase_items if v > 1e-12]
            if pos:
                weights = list(range(1, len(pos) + 1))
                value = sum(w * v for w, v in zip(weights, pos)) / sum(weights)
            else:
                value = fallback
            if target // p == current_start // p:
                value *= level
        out.append(float(max(0.0, value)) if math.isfinite(value) else 0.0)
    return out

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    if horizon <= 0:
        return []
    x = []
    for v in history:
        try:
            z = float(v)
            x.append(z if math.isfinite(z) else 0.0)
        except (TypeError, ValueError):
            x.append(0.0)
    if not x:
        return [0.0] * horizon
    p = 24 if 'hour' in frequency.lower() else max(2, min(24, len(x) // 4))
    n = len(x)
    offset = n % p
    start = n - offset
    prefix = x[start:n]
    candidates = []
    if prefix:
        scale = statistics.median([abs(v) for v in prefix if abs(v) > 1e-12]) if any(abs(v) > 1e-12 for v in prefix) else 1.0
        scale = max(scale, 1e-6)
        for c in range(0, start, p):
            if c + offset + horizon > n:
                continue
            sample = x[c:c + offset]
            if len(sample) != len(prefix):
                continue
            errors = [abs(a - b) / scale for a, b in zip(prefix, sample)]
            zero_disagreement = sum((a <= 1e-12) != (b <= 1e-12) for a, b in zip(prefix, sample))
            score = sum(errors) / max(1, len(errors)) + zero_disagreement / max(1, len(errors))
            candidates.append((score, c))
    if candidates:
        candidates.sort()
        chosen = candidates[0][1]
        out = x[chosen + offset:chosen + offset + horizon]
        return [float(max(0.0, v)) for v in out]
    out = []
    for k in range(horizon):
        phase = (n + k) % p
        vals = [x[i] for i in range(phase, n, p)][-3:]
        if not vals:
            out.append(0.0)
        elif sum(v <= 1e-12 for v in vals) >= 2:
            out.append(0.0)
        else:
            pos = [v for v in vals if v > 1e-12]
            out.append(float(statistics.median(pos)) if pos else 0.0)
    return out

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    if horizon <= 0:
        return []
    x = []
    for v in history:
        try:
            z = float(v)
            x.append(z if math.isfinite(z) else 0.0)
        except (TypeError, ValueError):
            x.append(0.0)
    if not x:
        return [0.0] * horizon
    p = 24 if 'hour' in frequency.lower() else max(2, min(24, len(x) // 4))

    def predict(train, steps, method):
        m = len(train)
        result = []
        global_pos = [v for v in train[-3 * p:] if v > 1e-12]
        fallback = statistics.median(global_pos) if global_pos else 0.0
        for k in range(steps):
            phase = (m + k) % p
            vals = [train[i] for i in range(phase, m, p)][-4:]
            if len(vals) >= 3 and sum(v <= 1e-12 for v in vals) >= 3:
                result.append(0.0)
                continue
            pos = [v for v in vals if v > 1e-12]
            if method == 'seasonal':
                value = vals[-1] if vals else fallback
            elif method == 'local_mean':
                recent = pos[-3:]
                if recent:
                    weights = list(range(1, len(recent) + 1))
                    value = sum(w * v for w, v in zip(weights, recent)) / sum(weights)
                else:
                    value = fallback
            else:
                if len(pos) >= 2:
                    trend = 0.5 * (pos[-1] - pos[-2])
                    limit = 0.35 * max(pos[-1], 1e-6)
                    trend = max(-limit, min(limit, trend))
                    value = pos[-1] + trend
                elif pos:
                    value = pos[-1]
                else:
                    value = fallback
            result.append(float(max(0.0, value)) if math.isfinite(value) else 0.0)
        return result

    methods = ['seasonal', 'local_mean', 'damped_trend']
    scores = {m: [] for m in methods}
    first_origin = max(2 * p, len(x) - 4 * p)
    origins = list(range(first_origin, len(x), p))
    for origin in origins:
        steps = min(p, len(x) - origin)
        if steps <= 0:
            continue
        actual = x[origin:origin + steps]
        for method in methods:
            pred = predict(x[:origin], steps, method)
            terms = []
            for a, b in zip(actual, pred):
                denom = abs(a) + abs(b)
                terms.append(0.0 if denom <= 1e-12 else 200.0 * abs(a - b) / denom)
            scores[method].append(sum(terms) / len(terms))
    ranked = []
    for method in methods:
        value = sum(scores[method]) / len(scores[method]) if scores[method] else float('inf')
        ranked.append((value, method))
    ranked.sort()
    chosen = ranked[0][1] if math.isfinite(ranked[0][0]) else 'seasonal'
    return predict(x, horizon, chosen)
